const abis = {
  'arm64-v8a': 6985168,
  'armeabi-v7a': 4859120,
  'x86': 7362736,
  'x86_64': 7098048
};
const total = Object.values(abis).reduce((a, b) => a + b, 0);
console.log('Las cuatro juntas:', total, 'bytes');
for (const [abi, bytes] of Object.entries(abis)) {
  const pct = (100 * bytes / total).toFixed(1);
  console.log(abi.padEnd(12), String(bytes).padStart(9), pct + ' % del total');
}
const ahorro = 100 * (1 - abis['arm64-v8a'] / total);
console.log('Un teléfono arm64 se ahorra', ahorro.toFixed(1) + ' %');
